function Header() {
  return (
    <h1>WebCréa Admin</h1>
    <p>Back-office de l'agence</p>
  );
}

const [messages, setMessages] = useState([]);

function handleAdd(message) {
  messages.push(message);
  setMessages(messages);
}

const [query, setQuery] = useState('');

<input
  value={query}
  onChange={(e) => setQuery(e.target.value)}
/>

const [messages, setMessages] = useState();

useEffect(() => {
  fetch('/api/messages')
    .then((res) => res.json())
    .then(setMessages);
}, []);

return <ul>{messages.map((m) => <li key={m.id}>{m.sujet}</li>)}</ul>;
